import {escapeHtml as h,number} from './domain.js';
export function unitLevel(value){if(value==null||!Number.isFinite(Number(value)))return '<span class="unit-level unknown" title="Niveau non enregistré">N?</span>';const n=Math.max(0,Number(value)),mixed=Math.abs(n-Math.round(n))>.00001;return `<span class="unit-level" title="${mixed?'Niveau moyen pondéré des unités':'Niveau technologique des unités'}">N${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(n)}${mixed?' moy.':''}</span>`;}
export function forceLevelGroups(forces,key,fallbackRace){const groups=new Map();for(const f of forces){const quantity=key==='soldiers'?Number(f.ground_soldiers||0)+Number(f.soldiers||0):Number(f[key]||0);if(!quantity)continue;const race=f.race||fallbackRace,level=f[key==='soldiers'?'army_tech':'ship_tech']??null,id=race+':'+level;if(!groups.has(id))groups.set(id,{race,level,quantity:0});groups.get(id).quantity+=quantity;}return [...groups.values()].sort((a,b)=>String(a.race).localeCompare(String(b.race))||Number(a.level)-Number(b.level));}
export function forceLevelBadges(forces,key,race){return forceLevelGroups(forces,key,race).map(g=>`<span class="force-level-count">${unitLevel(g.level)}<small>×${number(g.quantity)}</small></span>`).join('');}
